import React from 'react';
import './BrandLogo.css';

// The original artwork in /public is the fallback; /public/brand holds a lighter lossless WebP copy of it,
// generated by `npm run brand-assets`.
// Logo and favicon files keep their URLs when replaced and browsers cache them for a day, so bump this after
// swapping the artwork to make every browser fetch the new files.
export const BRAND_VERSION = '2';

const FILES = {
  color: {
    webp: `/brand/healthcredstat-logo-600.webp?v=${BRAND_VERSION}`,
    original: `/healthcredstat-logo.png?v=${BRAND_VERSION}`,
  },
  white: {
    webp: `/brand/healthcredstat-logo-white-600.webp?v=${BRAND_VERSION}`,
    original: `/healthcredstat-logo-white.png?v=${BRAND_VERSION}`,
  },
} as const;

interface BrandLogoProps {
  variant?: keyof typeof FILES;
  className?: string;
  /** Intrinsic size attributes; they reserve space so the page doesn't shift when the image loads. */
  width: number;
  height: number;
  loading?: 'eager' | 'lazy';
}

/** The HealthCredSTAT logo. */
export function BrandLogo({ variant = 'color', className, width, height, loading = 'lazy' }: BrandLogoProps) {
  const files = FILES[variant];
  return (
    <picture className="brand-logo">
      <source type="image/webp" srcSet={files.webp} />
      <img
        src={files.original}
        alt="HealthCredSTAT"
        width={width}
        height={height}
        className={className}
        loading={loading}
        decoding="async"
      />
    </picture>
  );
}

export default BrandLogo;
